-- pulseCount
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'pulseCount' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'pulseCount');
  END LOOP;
END
$authz$;
ALTER TABLE public."pulseCount" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."pulseCount" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_employee_role())::text[]));

